import pandas as pd
import numpy as np

# Load the data
df = pd.read_csv('chunks_csv/outlierr/2021_ghg.csv')
adjacency_path = pd.read_csv('chunks_csv/borough_adjacency.csv')

# Ensure the borough names match between the two datasets
df['borough'] = df['borough'].str.strip()
adjacency_path['borough'] = adjacency_path['borough'].str.strip()
adjacency_path['neighbor'] = adjacency_path['neighbor'].str.strip()

# Identify neighbors for each borough
neighbors = {}
for index, row in adjacency_path.iterrows():
    if row['borough'] not in neighbors:
        neighbors[row['borough']] = []
    neighbors[row['borough']].append(row['neighbor'])

# Compute neighborhood averages
neighborhood_averages = {}
for borough, neighs in neighbors.items():
    if borough != 'City of London':  # exclude City of London from its own neighborhood
        neigh_values = df.loc[df['borough'].isin(neighs), 'GHG_value'].dropna().values
        if len(neigh_values) > 0:
            neighborhood_averages[borough] = np.mean(neigh_values)
        else:
            neighborhood_averages[borough] = np.nan

# Compute neighborhood averages for City of London
city_neighs = neighbors['City of London']
city_neigh_values = df.loc[df['borough'].isin(city_neighs), 'GHG_value'].dropna().values
if len(city_neigh_values) > 0:
    neighborhood_averages['City of London'] = np.mean(city_neigh_values)
else:
    neighborhood_averages['City of London'] = np.nan

# Calculate z-score for City of London
city_value = df.loc[df['borough'] == 'City of London', 'GHG_value'].values[0]
if not np.isnan(neighborhood_averages['City of London']):
    z_score = (city_value - neighborhood_averages['City of London']) / np.std(df.loc[df['borough'].isin(city_neighs), 'GHG_value'].dropna().values)
else:
    z_score = np.nan

# Handle missing values
data_points_used = len(df['GHG_value'].dropna())
if np.isnan(z_score):
    # impute missing values using mean imputation
    df['GHG_value'] = df['GHG_value'].fillna(df['GHG_value'].mean())
    city_value = df.loc[df['borough'] == 'City of London', 'GHG_value'].values[0]
    city_neigh_values = df.loc[df['borough'].isin(city_neighs), 'GHG_value'].dropna().values
    if len(city_neigh_values) > 0:
        neighborhood_averages['City of London'] = np.mean(city_neigh_values)
    else:
        neighborhood_averages['City of London'] = np.mean(df['GHG_value'].dropna())
    z_score = (city_value - neighborhood_averages['City of London']) / np.std(df.loc[df['borough'].isin(city_neighs), 'GHG_value'].dropna().values)

# Determine outlier status
if np.isnan(z_score):
    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {z_score})")
elif z_score > 2:
    print(f"FINAL ANSWER: OUTLIER - HIGH (z = {z_score})")
elif z_score < -2:
    print(f"FINAL ANSWER: OUTLIER - LOW (z = {z_score})")
else:
    print(f"FINAL ANSWER: NOT AN OUTLIER (z = {z_score})")

print(f"data_points_used = {data_points_used}")
